def model(chunks):
 think=''; answer=''; live=False
 for text in chunks:
  if not live:
   p=text if think or not text.startswith(' ') else text[1:]
   think+=p
   if '</think>' in think: live=True
  else: answer+=text
 return {'thinking':think,'history':answer.strip(),'live':live}
for chunks in [['reason</think>','Answer'],['reason</think>Answer'],['reason</thi','nk>Answer'],['reason only']]:
 print(json.dumps({'chunks':chunks,'result':model(chunks)}))
